let img;
let t;
let N=3000;
let count=0;
Particle [] particles = new Array(N);
function setup(){
  background(255);
  img = loadImage("https://openprocessing.org/sketch/1869326/files/20220611-EP5A1587-106.jpg");
  createCanvas(1007, 1007);
  //image(img,0,0);
  t = 0.0;
  img.loadPixels();
  for (i=0; i<N; i++){
    particles[i] = new Particle(random(200,300));
  }
}
function draw(){
  t+=0.001;
  count += 1;
  for(i=0; i<N; i++){
    particles[i].update();
    particles[i].display();
  }
  if(count%10==0){
  //  saveFrame("JF-#####.png");
  }

}


// === Tab: Particle ===
class Particle{
  x,y,lifetime,time,xo,yo;
  c;
  constructor(_lifetime){
    //let r = random(width/3*2);
    //let theta = radians(random(360));
    //x = r*cos(theta)+width/2;
    //y = r*sin(theta)+height/2;
    x = random(0,width);
    y = random(0,height);
    xo = x;
    yo = y;
    lifetime = _lifetime;
    time = 0;
  }
  function update(){
    let dx = 4*noise(x/100,y/100,t)-2;
    let dy = 4*noise((x+100)/100,(y+100)/100,t)-2;
    xo = x;
    yo = y;
    x += dx;
    y += dy;

    time += 1;
    if (time>lifetime){
      //let r = random(width/3*2);
      //let theta = radians(random(360));
      //x = r*cos(theta)+width/2;
      //y = r*sin(theta)+height/2;
      x = random(0,width);
      y = random(0,height);
      xo = x;
      yo = y;
      time = 0;
    }
    if(x<0){
      x+=width;
      xo = x;
    }
    if(x>=width){
      x-=width;
      xo = x;
    }
    if(y<0){
      y+=height;
      yo = y;
    }
    if(y>=height){
      y-=height;
      yo = y;
    }
  }
  function display(){
    //println((int(x)%width) + (int(y)%height) * img.width);
    c = img.pixels[(int(x)%width) + (int(y)%height) * img.width];
    stroke(c);
    strokeWeight(0.1);
    line(x,y,xo,yo);
  }
}

